import{_ as r}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as n,C as s,o as d,c as f,al as i,j as t,a as o,E as l}from"./chunks/framework.7vp1BMOE.js";const P=JSON.parse('{"title":"Режим зльоту (Мультикоптер)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_mc/takeoff.md","filePath":"uk/flight_modes_mc/takeoff.md"}'),m={name:"uk/flight_modes_mc/takeoff.md"},h={tabindex:"0"},_={id:"takeoff-from-a-moving-platform-boat-deck",tabindex:"-1"};function c(u,e,p,g,k,v){const a=s("Badge");return d(),f("div",null,[e[10]||(e[10]=i('<h1 id="режим-зльоту-мультикоптер" tabindex="-1">Режим зльоту (Мультикоптер) <a class="header-anchor" href="#режим-зльоту-мультикоптер" aria-label="Permalink to &quot;Режим зльоту (Мультикоптер)&quot;">​</a></h1><img src="'+r+'" title="Position fix required (e.g. GPS)" width="30px"><p>The <em>Takeoff</em> flight mode causes the vehicle to take off to a specified height and wait for further input.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Режим автоматичний - для керування апаратом не потрібно втручання користувача.</li><li>Режим потребує принаймні дійсної локальної оцінки позиції (не потребує глобальної позиції). <ul><li>Літаючі транспортні засоби не можуть переключатися на цей режим без глобального положення.</li><li>Літаючі транспортні засоби перейдуть в режим аварійної безпеки, якщо втратять оцінку положення.</li><li>Роззброєні транспортні засоби можуть переключатися в режим без дійсної оцінки позиції, але не можуть озброюватися.</li></ul></li><li>Перемикачі радіокерування можна використовувати для зміни режимів польоту.</li><li>Stick movement will <a href="#MAN_OVERRIDE_SPD">by default</a> change the vehicle to <a href="./../flight_modes_mc/position">Position mode</a> unless prevented by the active failsafe state.</li><li>The <a href="./../config/safety#failure-detector">Failure Detector</a> will automatically stop the engines if there is a problem on takeoff.</li></ul></div><h2 id="технічнии-підсумок" tabindex="-1">Технічний підсумок <a class="header-anchor" href="#технічнии-підсумок" aria-label="Permalink to &quot;Технічний підсумок&quot;">​</a></h2><p>A multi rotor ascends vertically to the altitude defined in <a href="./../advanced_config/parameter_reference#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a> and holds position.</p><p>Stick movement will change the vehicle to <a href="./../flight_modes_mc/position">Position mode</a> (by <a href="#MAN_OVERRIDE_SPD">default</a>).</p><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position"><code>mode_req_local_position</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point</li></ul><h3 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h3><p>Взліт впливається наступними параметрами:</p>',12)),t("table",h,[e[6]||(e[6]=t("thead",null,[t("tr",null,[t("th",null,"Parameter"),t("th",null,"Опис")])],-1)),t("tbody",null,[e[4]||(e[4]=t("tr",null,[t("td",null,[t("a",{id:"MIS_TAKEOFF_ALT"}),t("a",{href:"./../advanced_config/parameter_reference#MIS_TAKEOFF_ALT"},"MIS_TAKEOFF_ALT")]),t("td",null,"Цільова висота під час злітання (типово: 2.5м)")],-1)),e[5]||(e[5]=t("tr",null,[t("td",null,[t("a",{id:"MPC_TKO_SPEED"}),t("a",{href:"./../advanced_config/parameter_reference#MPC_TKO_SPEED"},"MPC_TKO_SPEED")]),t("td",null,"Швидкість підйому (за замовчуванням: 1.5м/с)")],-1)),t("tr",null,[e[3]||(e[3]=t("td",null,[t("a",{id:"MAN_OVERRIDE_SPD"}),t("a",{href:"./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD"},"MAN_OVERRIDE_SPD")],-1)),t("td",null,[e[0]||(e[0]=o("Speed (normalized stick travel per second) above which moving the sticks controlling a multicopter (or VTOL in hover) gives control back to the pilot by switching to ",-1)),e[1]||(e[1]=t("a",{href:"./../flight_modes_mc/position"},"Position mode",-1)),e[2]||(e[2]=o(" (or Altitude mode if position is unavailable). At the default value of 1 a half-stick movement in ~0.5 s triggers it; lower is more sensitive. A stick held statically has zero speed and will not trigger. Set to -1 to disable. ",-1)),l(a,{type:"tip",text:"PX4 v1.18"})])])])]),t("h2",_,[e[7]||(e[7]=o("Takeoff From a Moving Platform (Boat Deck) ",-1)),l(a,{type:"tip",text:"PX4 v1.18"}),e[8]||(e[8]=o()),e[9]||(e[9]=t("a",{class:"header-anchor",href:"#takeoff-from-a-moving-platform-boat-deck","aria-label":'Permalink to "Takeoff From a Moving Platform (Boat Deck) <Badge type="tip" text="PX4 v1.18" />"'},"​",-1))]),e[11]||(e[11]=i('<p>Automatic takeoff from a moving platform, such as a boat deck, is supported. The multicopter climbs and holds the point where it left the deck, rather than following the boat.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Given that the vehicle holds the point where it left the deck and does not travel along with the boat, always take off from the <strong>back (stern) of the boat</strong>, with clear open space behind it. Taking off from the bow or the middle of the boat can leave it behind across the deck and into masts, antennas, superstructure, or crew.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Takeoff from a moving platform is only supported in <a href="#technical-summary">Takeoff mode</a> (or the equivalent coordinate-less takeoff commanded from a ground station), not as part of a <a href="./../flight_modes_mc/mission">Mission</a>. To run a mission from a boat, take off first in Takeoff mode and then start the mission once the vehicle is airborne.</p></div><p>The moving-platform case can be exercised in simulation with the Gazebo <a href="./../sim_gazebo_gz/worlds#moving-platform">Moving Platform world</a>.</p><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/throw_launch">Throw Launch (MC)</a></li><li><a href="./../flight_modes_fw/takeoff">Takeoff Mode (FW)</a></li></ul>',6))])}const q=n(m,[["render",c]]);export{P as __pageData,q as default};
